def grade_letter(score):
    if score >= 90:
        return 'A'
    if score >= 80:
        return 'B'
    if score >= 70:
        return 'C'
    if score >= 60:
        return 'D'
    return 'F'

reference_tests:
def test_a():
    assert grade_letter(95) == 'A'

def test_a_boundary():
    assert grade_letter(90) == 'A'

def test_b():
    assert grade_letter(85) == 'B'
    assert grade_letter(80) == 'B'

def test_c():
    assert grade_letter(70) == 'C'

def test_d():
    assert grade_letter(60) == 'D'

def test_f():
    assert grade_letter(59) == 'F'
    assert grade_letter(0) == 'F'

def test_just_below_a():
    assert grade_letter(89) == 'B'
